#include "fluxrenderqueue.h"

int FluxRenderQueue::enqueue(const FluxRenderJob&job){FluxQueuedRender q;q.job=job;m_jobs.push_back(q);return m_jobs.size()-1;}
void FluxRenderQueue::clear(){m_jobs.clear();m_cancelled=false;}
bool FluxRenderQueue::process(const std::function<QImage(int)>&renderer,QString*error){m_cancelled=false;for(auto&q:m_jobs){q.state=QStringLiteral("Rendering");q.progress=0;q.error.clear();const int start=q.job.settings.startFrame;const int end=qMax(start,q.job.settings.endFrame);const int total=end-start+1;if(q.job.format.compare("png",Qt::CaseInsensitive)==0||q.job.format.compare("jpeg",Qt::CaseInsensitive)==0||q.job.format.compare("webp",Qt::CaseInsensitive)==0||q.job.format.compare("svg",Qt::CaseInsensitive)==0){QImage image=renderer(start);const QString ext=q.job.format.toLower();bool ok=false;if(ext=="svg")ok=FluxExportEngine::exportSvgRaster(image,q.job.output,q.job.settings,&q.error);else ok=FluxExportEngine::exportImage(image,q.job.output,q.job.settings,&q.error);if(!ok){q.state="Failed";if(error)*error=q.error;return false;}q.progress=1.0;q.state="Complete";continue;}bool ok=FluxExportEngine::exportAnimated(renderer,q.job,&q.error);if(!ok){q.state="Failed";if(error)*error=q.error;return false;}q.progress=1.0;q.state="Complete";if(m_cancelled){q.state="Cancelled";break;}Q_UNUSED(total);}return !m_cancelled;}
